// ─── Component: Modal ─────────────────────────────────────────────────────────
function Modal({ isOpen, onClose, onConfirm, filename }) {
  const overlay = document.getElementById('delete-modal-overlay');

  if (isOpen) {
    overlay.classList.add('is-open');
    // Trap focus inside modal when open
    setTimeout(() => {
      const cancelBtn = document.getElementById('modal-cancel-btn');
      if (cancelBtn) cancelBtn.focus();
    }, 50);
  } else {
    overlay.classList.remove('is-open');
  }
}

// ─── Component: ImagePreviewPage (state + render) ─────────────────────────────
const PageState = {
  modalOpen: false,
  deleted: false,
};

function openModal() {
  PageState.modalOpen = true;
  Modal({ isOpen: true });
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  PageState.modalOpen = false;
  Modal({ isOpen: false });
  document.body.style.overflow = '';
}

function confirmDelete() {
  closeModal();

  // Show deleted toast notification
  const toast = document.getElementById('toast');
  toast.classList.add('toast--visible');
  setTimeout(() => toast.classList.remove('toast--visible'), 3500);

  // Grey out the image to reflect deletion
  const imgPanel = document.querySelector('.image-panel img');
  const actions = document.querySelector('.actions');
  if (imgPanel) {
    imgPanel.style.transition = 'filter 0.4s ease, opacity 0.4s ease';
    imgPanel.style.filter = 'grayscale(1)';
    imgPanel.style.opacity = '0.35';
  }
  if (actions) {
    actions.innerHTML = `<p style="text-align:center;color:var(--text-secondary);font-size:0.85rem;">Image deleted from library.</p>`;
  }
}

